local autoingPathBg = "UIAtlas/FightTeam/EntrustTeam/auto_bg_text_autoing"
local defaultPathBg = "UIAtlas/FightTeam/EntrustTeam/auto_bg_text_selected"
local lockPathBg = "UIAtlas/FightTeam/EntrustTeam/auto_bg_text_lock"
