local UIEntrustTasksSecondSelectNode = Class("UIEntrustTasksSecondSelectNode")
function UIEntrustTasksSecondSelectNode:__init()
    self.__callback = nil
    self.toast = nil
end

function UIEntrustTasksSecondSelectNode:__delete()
    self.__callback = nil
    self.toast = nil
    self.controller = nil
end

---SetCallBack
---设置单击回调函数
function UIEntrustTasksSecondSelectNode:SetCallBack(cb)
    self.__callback = cb
end

function UIEntrustTasksSecondSelectNode:Awake()
    UIEventProxy.Create(self.controller.gameObject.transform:Find("ImgBg").gameObject).onPointerClick = function()
        if type(self.__callback) == 'function' then
            self.__callback()
        end
        if type(self.toast) == 'function' then
            self.toast()
        end
    end
end

function UIEntrustTasksSecondSelectNode:FreshBaseUI(data)
    local isUnlockEntrust = QuestConfMgr:GetInstance():IsUnlockEntrust(data.id)--解锁了委托
    local isUnlockQuest = QuestConfMgr:GetInstance():IsUnlockQuest(data.id)
    local vo = QuestConfMgr:GetInstance():GetQuestVoById(data.id)
    CfUtils.FillText(self.TxtcheckpointName, vo.label)
    if isUnlockEntrust then
        local isLevelEntrusting = (teamComponent:GetEntrustQueueDataByQuestId(data.id) and true or false)
        if isLevelEntrusting then
            CfUtils.FillImage(self.ImgBg, autoingPathBg)
            CfUtils.FillText(self.TxtCommissioned, localize("委托中"))
            CfUtils.SetColor(self.TxtCommissioned, XLuaUtils.HexToColor("37AFA7"))
            KTool.SetActive(self.TxtCommissioned, true)
            self.toast = function()
                GameUtils.Toast(localize("当前关卡正在委托中"))
            end
        else
            KTool.SetActive(self.TxtCommissioned, false)
            CfUtils.FillImage(self.ImgBg, defaultPathBg)
            self.toast = function()
                
            end
        end
    else
        CfUtils.FillImage(self.ImgBg, lockPathBg)
        if isUnlockQuest then
            CfUtils.FillText(self.TxtCommissioned, "——")
            CfUtils.SetColor(self.TxtCommissioned, XLuaUtils.HexToColor("C3BEBE"))
            KTool.SetActive(self.TxtCommissioned, true)
            self.toast = function()
                GameUtils.Toast(localize("当前关卡未达成三星条件"))
            end
        else
            KTool.SetActive(self.TxtCommissioned, false)
            self.toast = function()
                GameUtils.Toast(localize("当前关卡未解锁"))
            end
        end
    end
    KTool.SetActive(self.Imglock, not isUnlockQuest)
end

function UIEntrustTasksSecondSelectNode:OnDestroy()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end

return UIEntrustTasksSecondSelectNode